import { createHash } from "node:crypto";
import { readdirSync, readFileSync } from "node:fs";
import { createServer, type Server } from "node:net";
import { join, relative } from "node:path";
import { describe, expect, it } from "vitest";
import { createTempProject, freePort, parseEnvelope, runFlisk } from "../../test-support/index.js";

/** A native project with a planted generated file, so a dry run that writes anything is visible. */
function project(port: number, command = "node server.js", extraPort?: number): string {
  return createTempProject({
    resources: {
      api: {
        appType: "backend",
        schemaVersion: 1,
        command,
        port,
      },
      ...(extraPort === undefined
        ? {}
        : {
            worker: {
              appType: "backend",
              schemaVersion: 1,
              command: "node worker.js",
              port: extraPort,
            },
          }),
    },
    generated: { "marker.txt": "generated by the test\n" },
  });
}

/** Content hash of every file in the project, generated outputs included. */
function hashTree(root: string): string {
  const files: string[] = [];
  const walk = (dir: string): void => {
    for (const entry of readdirSync(dir, { withFileTypes: true })) {
      const path = join(dir, entry.name);
      if (entry.isDirectory()) walk(path);
      else if (entry.isFile()) files.push(path);
    }
  };
  walk(root);
  const hash = createHash("sha256");
  for (const path of files.sort()) {
    hash.update(`${relative(root, path).split("\\").join("/")}\0${readFileSync(path, "utf-8")}\0`);
  }
  return hash.digest("hex");
}

async function listen(port = 0): Promise<{ server: Server; port: number }> {
  const server = createServer();
  await new Promise<void>((resolve) => server.listen(port, "127.0.0.1", resolve));
  return { server, port: (server.address() as { port: number }).port };
}

describe("flisk up --dry-run preflight (native runtime)", () => {
  it("reports an occupied service port with ok:false, exit 1 and no writes", async () => {
    const { server, port } = await listen();
    try {
      const root = project(port);
      const before = hashTree(root);
      const run = runFlisk(["up", "--dry-run", "--json"], { cwd: root });
      expect(run.status).toBe(1);
      const envelope = parseEnvelope(run.stdout);
      expect(envelope.data).toEqual({ ok: false, runtime: "native", dryRun: true });
      expect(envelope.errors).toEqual([
        {
          code: "PORT_IN_USE",
          message: expect.stringContaining(`Port ${port} for service "api" is already in use`),
        },
      ]);
      expect(envelope.errors[0]?.message).toContain('change "port" in the service.json');
      expect(hashTree(root)).toBe(before);
    } finally {
      await new Promise<void>((resolve) => server.close(() => resolve()));
    }
  });

  it("reports duplicate service ports with both names and the fix", async () => {
    const port = await freePort();
    // Two service.json files sharing one port: the same plan error a real `flisk up` refuses on.
    const root = project(port, "node server.js", port);
    const before = hashTree(root);
    const run = runFlisk(["up", "--dry-run", "--json"], { cwd: root });
    expect(run.status).toBe(1);
    const envelope = parseEnvelope(run.stdout);
    expect(envelope.data).toEqual({ ok: false, runtime: "native", dryRun: true });
    expect(envelope.errors[0]).toMatchObject({ code: "INVALID_SERVICE_CONFIG" });
    expect(envelope.errors[0]?.message).toContain('services "api" and "worker" both use port');
    expect(envelope.errors[0]?.message).toContain('Fix: Give each service a different "port"');
    expect(hashTree(root)).toBe(before);
  });

  it("reports a missing start program with the service name and the fix", async () => {
    const root = project(await freePort(), "flisk-missing-program-4679 --serve");
    const before = hashTree(root);
    const run = runFlisk(["up", "--dry-run", "--json"], { cwd: root });
    expect(run.status).toBe(1);
    const envelope = parseEnvelope(run.stdout);
    expect(envelope.data).toEqual({ ok: false, runtime: "native", dryRun: true });
    expect(envelope.errors).toEqual([
      {
        code: "NATIVE_COMMAND_NOT_FOUND",
        message:
          'service "api" runs flisk-missing-program-4679, which is not installed (not found on PATH). Install it, or change "command" in its service.json.',
      },
    ]);
    expect(hashTree(root)).toBe(before);
  });

  it("prints the unchanged plan and exits 0 when every check passes", async () => {
    const root = project(await freePort());
    const before = hashTree(root);
    const run = runFlisk(["up", "--dry-run", "--json"], { cwd: root });
    expect(run.status).toBe(0);
    const envelope = parseEnvelope(run.stdout);
    expect(envelope.data).toEqual({
      ok: true,
      dryRun: true,
      runtime: "native",
      stack: null,
      services: ["api"],
      startOrder: [["api"]],
    });
    expect(envelope.errors).toEqual([]);
    expect(hashTree(root)).toBe(before);
  });
});
